#!/bin/bash\n# Complete smg4OS build process\n# This script orchestrates all build steps\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\necho \"[INFO] Starting complete smg4OS build...\"\necho \"\"\n\n# Step 1: Main build\necho \"=== Step 1: Building Core System ===\"\n\"$SCRIPT_DIR/build.sh\"\n\necho \"\"\necho \"=== Step 2: Creating ISO Image ===\"\n\"$SCRIPT_DIR/create-iso.sh\"\n\necho \"\"\necho \"[SUCCESS] Complete build finished!\"\necho \"\"\necho \"Output directory: $(dirname $SCRIPT_DIR)/build\"\necho \"ISO location: $(dirname $SCRIPT_DIR)/iso\"\necho \"\"\necho \"To test the ISO:\"\necho \"  qemu-system-x86_64 -cdrom iso/smg4OS-latest.iso -m 2G -enable-kvm\"\necho \"\"\necho \"To write to USB:\"\necho \"  sudo dd if=iso/smg4OS-latest.iso of=/dev/sdX bs=4M\"\necho \"\"\n"